import{_ as s,o as e,c as a,a3 as t}from"./chunks/framework.DhF4LrUq.js";const k=JSON.parse('{"title":"Configure SCIM provisioning","description":"Configure SCIM provisioning - connect your identity provider so joins, moves, and levers flow automatically into ShipperDog.","frontmatter":{"description":"Configure SCIM provisioning - connect your identity provider so joins, moves, and levers flow automatically into ShipperDog."},"headers":[],"relativePath":"how-to/console/scim-provisioning.md","filePath":"how-to/console/scim-provisioning.md"}'),n={name:"how-to/console/scim-provisioning.md"};function o(r,i,p,h,l,d){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="configure-scim-provisioning" tabindex="-1">Configure SCIM provisioning <a class="header-anchor" href="#configure-scim-provisioning" aria-label="Permalink to &quot;Configure SCIM provisioning&quot;">​</a></h1><p>SCIM is the automation layer over membership: your identity provider pushes users and groups, and ShipperDog keeps the rosters in step — a joiner in the IdP becomes a member, a leaver is deprovisioned with their accesses revoked. One live connector token per organization; configuration by Organization Administrators through the organization API.</p><p>The provisioning semantics — the joiner and leaver cascade — are covered in <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO</a>.</p><h2 id="generate-the-connector-token" tabindex="-1">Generate the connector token <a class="header-anchor" href="#generate-the-connector-token" aria-label="Permalink to &quot;Generate the connector token&quot;">​</a></h2><ol><li><p>Generate (or rotate) the token:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/organizations/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scim-config/token&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li><li><p>Copy the plaintext <strong>now</strong> — it begins with <code>sds_</code> and appears exactly once, in this response. Store it in your IdP&#39;s credential vault.</p></li><li><p>Rotation is atomic: a new token kills the old one in the same transaction. Revocation (<code>DELETE .../scim-config/token</code>) freezes SCIM entirely until a new token exists — the provisioning off-switch.</p></li></ol><h2 id="author-the-mapping-rules" tabindex="-1">Author the mapping rules <a class="header-anchor" href="#author-the-mapping-rules" aria-label="Permalink to &quot;Author the mapping rules&quot;">​</a></h2><p>Write the settings and rules in one declarative state:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/organizations/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scim-config&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;enabled&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;groupMappings&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;groupDisplayName&quot;: &quot;shipperdog-release-managers&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;organizationRole&quot;: &quot;RELEASE_MANAGER&quot; }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span></span></code></pre></div><p>The mapping rules key on the group <code>displayName</code> your IdP pushes and decide what each group grants — organization roles, tenant memberships. Keep <code>enabled: false</code> while composing; flip it to go live (an enabled connector whose rules are wrong provisions the wrong shape — test with one group first).</p><h2 id="point-the-idp-at-shipperdog" tabindex="-1">Point the IdP at ShipperDog <a class="header-anchor" href="#point-the-idp-at-shipperdog" aria-label="Permalink to &quot;Point the IdP at ShipperDog&quot;">​</a></h2><p>Every provider gets the same three facts: the SCIM base URL <code>https://&lt;your-deployment&gt;/scim/v2</code>, the bearer token, and User + Group sync enabled.</p><ul><li><strong>Microsoft Entra ID</strong> — Enterprise application, Provisioning, automatic. Enable User and Group sync; group pushes carry the <code>displayName</code> your mapping rules key on.</li><li><strong>Okta</strong> — Application, Provisioning, SCIM 2.0.</li><li><strong>Google Workspace</strong> — sends no SCIM natively; a provisioning bridge supplies it (set <code>externalId</code> to the Google user id and send the account address as the primary email).</li></ul><p>Discovery is automatic: Entra and Okta probe <code>/scim/v2/ServiceProviderConfig</code> before their first write.</p><h2 id="watch-it-work" tabindex="-1">Watch it work <a class="header-anchor" href="#watch-it-work" aria-label="Permalink to &quot;Watch it work&quot;">​</a></h2><ul><li>A joiner pushed by the IdP is provisioned through an externalId-first upsert: a fresh user answers <code>201</code>, a replay <code>200</code>.</li><li>Group pushes map through your rules to roles and tenants.</li><li>A <strong>leaver</strong> (delete, or <code>active: false</code>) triggers the deprovision cascade — memberships and accesses follow the user out. A re-provision later rebuilds the account; that doctrine is part of the contract.</li></ul><p>Every leg is audited. A refused request answers SCIM&#39;s uniform 401 — the distinct reason rides the audit line, never the response.</p><div class="tip custom-block"><p class="custom-block-title">SSO first, SCIM second</p><p>SCIM assumes the identity story is settled — configure <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO</a> first, then layer provisioning on top so joiners land in a world they can actually sign in to.</p></div><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO (OIDC and SAML)</a> · <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO concepts</a> · <a href="/shipperdog/snapshot/roles/org-admin">org-admin quickstart</a></p>`,18)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
